for mc in d['meeting_chats']:
    if 'cofoaix_market' in str(mc).lower() or 'CoFoAIX_planning_1' in str(mc):
        text_artifacts.append(('meeting_chat', mc['id'], mc.get('text',''), ''))
for u in d['urls']:
    if 'cofoaix' in u.get('link','').lower() or 'market_research' in u.get('link','').lower():
        text_artifacts.append(('url', u['id'], u.get('link','') + ' ' + u.get('description',''), ''))
for msg in d['slack']:
    text = msg.get('Message', {}).get('User', {}).get('text', '')
    if 'cofoaix_market' in text.lower() or 'final_cofoaix_market' in text.lower() or 'latest_cofoaix_market' in text.lower():
        text_artifacts.append(('slack', msg['id'], text, msg['Channel'].get('name')))

print('Total artifacts:', len(text_artifacts))
for kind, mid, text, meta in text_artifacts:
    print(f'{kind}: {mid} ({meta})')
"

